public void populate()
{
    NDXC09P lNDXC09P;
    NDXC09PItemRoutingView lNDXC09PItemRoutingView;

    delete_from lNDXC09P where lNDXC09P.CSTR == curExt();

    insert_recordset lNDXC09P
        (CSTR, CCIC, CCICVER, CART)
    select
        DataAreaId, RouteId, Version, ItemId
    from lNDXC09PItemRoutingView;
}

public static str getVersion()
{
    str version;

    str activeField = SysComputedColumn::returnField(viewstr(NDXC09PItemRoutingView), tableStr(RouteVersion), fieldStr(RouteVersion, Active));
    str approvedField = SysComputedColumn::returnField(viewstr(NDXC09PItemRoutingView), tableStr(RouteVersion), fieldStr(RouteVersion, Approved));
    str nameField = SysComputedColumn::returnField(viewstr(NDXC09PItemRoutingView), tableStr(RouteVersion), fieldStr(RouteVersion, Name));
    str itemIdField = SysComputedColumn::returnField(viewstr(NDXC09PItemRoutingView), tableStr(RouteVersion), fieldStr(RouteVersion, ItemId));

    str activeExpression = SysComputedColumn::equalExpression(activeField,SysComputedColumn::comparisonLiteral(NoYes::Yes));
    str approvedExpression = SysComputedColumn::equalExpression(approvedField,SysComputedColumn::comparisonLiteral(NoYes::Yes));

    str isActiveAndApproved = SysComputedColumn::and2(activeExpression, approvedExpression);
    str isNotActiveAndApproved = SysComputedColumn::and2(SysComputedColumn::notEqualExpression(activeField,SysComputedColumn::comparisonLiteral(NoYes::Yes)), approvedExpression);

    //
    version = strFmt("(SELECT cast(count(RecId) + 1  as nvarchar(1))"
       + " FROM RouteVersion"
       + " WHERE RouteVersion.ItemId = %1"
       + " AND RouteVersion.Active = %2"
       + " AND RouteVersion.Approved = %3"
       + " AND RouteVersion.Name >= %4)", itemIdField, activeField, approvedField, nameField);

    return SysComputedColumn::if(isActiveAndApproved,
        SysComputedColumn::returnLiteral('1'),
        SysComputedColumn::if(isNotActiveAndApproved,
            version,
            SysComputedColumn::returnLiteral('0')));

    //Or as Case
    /*return strFmt(@'
        CASE
            WHEN %1 = 1 AND %2 = 1 THEN ''1''
            WHEN %1 = 0 AND %2 = 1 THEN
            CAST((
                SELECT COUNT(V2.RECID) + 1
                FROM %5 V2
                WHERE V2.ITEMID   = %3
                  AND V2.ACTIVE   = %1
                  AND V2.APPROVED = %2
                  AND V2.NAME    >= %4
            ) AS NVARCHAR(10))
        ELSE ''0''
        END',
        activeField,        // %1
        approvedField,      // %2
        itemIdField,        // %3
        nameField,     // %4
        'BOMVersion'       // %5 (Name der View in FROM-Klausel)
    );*/


}
